&lt;div class="" data-block="true" data-editor="5vjqq" data-offset-key="eopss-0-0"&gt;
&lt;div class="public-DraftStyleDefault-block public-DraftStyleDefault-ltr" data-offset-key="eopss-0-0"&gt;&lt;span data-offset-key="eopss-0-0"&gt;&lt;span data-text="true"&gt;With guidance and &lt;/span&gt;&lt;/span&gt;&lt;span class="style_handle__4nndx style_hasReplacements__2Gq83 style_feminine__2TtJP"&gt;&lt;span data-offset-key="eopss-1-0"&gt;&lt;span data-text="true"&gt;support&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span data-offset-key="eopss-2-0"&gt;&lt;span data-text="true"&gt; from our wider Advisory team, you will:&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
