&lt;/li&gt;
&lt;li class="public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR" data-block="true" data-editor="5vjqq" data-offset-key="1v2f2-0-0"&gt;
