&lt;div class="ng-tns-c879422873-771"&gt;
&lt;section id="processing-state-26" class="processing-state_container ng-tns-c879422873-771 is-gpi-avatar is-done-processing ng-trigger ng-trigger-processingStateShowHide ng-star-inserted"&gt;
