&lt;div class="c-message_kit__background p-message_pane_message__message c-message_kit__message" data-qa="message_container" data-qa-unprocessed="false" data-qa-placeholder="false" data-msg-ts="1767721326.693929" data-msg-channel-id="D05PRV9JACF"&gt;
